const originDocument = this.effect?.origin
  ? await fromUuid(this.effect.origin)
  : null;

const sourceItem =
  this.item
  ?? this.effect?.sourceItem
  ?? (this.effect?.parent?.documentName === "Item" ? this.effect.parent : null)
  ?? (originDocument?.documentName === "Item"
    ? originDocument
    : originDocument?.parent?.documentName === "Item"
      ? originDocument.parent
      : null);

if (!sourceItem) {
  ui.notifications.error("Totem: nie odnaleziono źródłowej cechy.");
  return;
}

const activeSource = sourceItem.effects?.contents?.[1];

if (!activeSource) {
  ui.notifications.error("Totem: brak efektu contents[1].");
  return;
}

const alreadyActive = Array.from(this.actor.effects ?? []).some(
  effect => effect.getFlag("neuroshima", "sourceEffect") === activeSource.uuid
);

if (alreadyActive) {
  ui.notifications.warn("Totem jest już aktywny.");
  return;
}

const totems = {
  constitution: { animal: "Niedźwiedź", attribute: "Budowa" },
  perception: { animal: "Sokół", attribute: "Percepcja" },
  cleverness: { animal: "Kojot", attribute: "Spryt" },
  dexterity: { animal: "Kot", attribute: "Zręczność" },
  charisma: { animal: "Wilk", attribute: "Charakter" }
};

const selectedAttribute = await this.chooseFromList(
  Object.entries(totems).map(([value, data]) => ({
    value,
    label: `${data.animal} — ${data.attribute}`
  })),
  "Wybierz postać Totemu.",
  "Totem"
);

if (!selectedAttribute || !totems[selectedAttribute]) return;

const selectedTotem = totems[selectedAttribute];

const roll = await this.rollAttributeTest(selectedAttribute, {
  difficulty: "problematic",
  isOpen: true,
  label: `Totem: ${selectedTotem.animal} — ${selectedTotem.attribute}`,
  testType: "totem",
  testSubtype: "activation",
  recipient: "actorOwner"
});

if (roll.cancelled) return;

if (!roll.success) {
  ui.notifications.warn("Nie udało się przyjąć postaci Totemu.");
  return;
}

const duplicate = Array.from(this.actor.effects ?? []).some(
  effect => effect.getFlag("neuroshima", "sourceEffect") === activeSource.uuid
);

if (duplicate) return;

const attributeKeys = [
  "constitution",
  "perception",
  "cleverness",
  "dexterity",
  "charisma"
];

const changes = attributeKeys.map(attributeKey => ({
  key: `system.attributeBonuses.${attributeKey}`,
  mode: CONST.ACTIVE_EFFECT_MODES.ADD,
  value: attributeKey === selectedAttribute ? 2 : -1,
  priority: 20
}));

await activeSource.applyEffect(this.actor, {
  name: `Totem — ${selectedTotem.animal}`,
  changes,
  "flags.neuroshima.totemAttribute": selectedAttribute,
  "flags.neuroshima.totemAnimal": selectedTotem.animal,
  "flags.neuroshima.totemStartedAt": Number(game.time?.worldTime ?? 0)
});

ui.notifications.info(`Przyjęto postać Totemu: ${selectedTotem.animal}.`);

const originDocument = this.effect?.origin
  ? await fromUuid(this.effect.origin)
  : null;

const sourceItem =
  this.item
  ?? this.effect?.sourceItem
  ?? (this.effect?.parent?.documentName === "Item" ? this.effect.parent : null)
  ?? (originDocument?.documentName === "Item"
    ? originDocument
    : originDocument?.parent?.documentName === "Item"
      ? originDocument.parent
      : null);

if (!sourceItem) {
  ui.notifications.error("Totem: nie odnaleziono źródłowej cechy.");
  return;
}

const activeSource = sourceItem.effects?.contents?.[1];
const fatigueSource = sourceItem.effects?.contents?.[2];

if (!activeSource || !fatigueSource) {
  ui.notifications.error("Totem: brak efektu contents[1] lub contents[2].");
  return;
}

const activeCopies = Array.from(this.actor.effects ?? []).filter(
  effect => effect.getFlag("neuroshima", "sourceEffect") === activeSource.uuid
);

if (!activeCopies.length) {
  ui.notifications.warn("Totem nie jest obecnie aktywny.");
  return;
}

const endReason = await this.chooseFromList(
  [
    { value: "choice", label: "Zakończ z własnej woli" },
    { value: "sleep", label: "Rozpocznij sen" }
  ],
  "W jaki sposób kończy się postać Totemu?",
  "Wyłączenie Totemu"
);

if (!endReason) return;

const currentTime = Number(game.time?.worldTime ?? 0);

const activeDurations = activeCopies
  .map(effect => {
    const rawStartedAt = effect.getFlag("neuroshima", "totemStartedAt");

    if (
      rawStartedAt === null
      || rawStartedAt === undefined
      || rawStartedAt === ""
    ) {
      return null;
    }

    const startedAt = Number(rawStartedAt);

    return Number.isFinite(startedAt)
      ? Math.max(0, currentTime - startedAt)
      : null;
  })
  .filter(value => value !== null);

if (!activeDurations.length) {
  ui.notifications.error("Totem: nie udało się ustalić czasu aktywacji.");
  return;
}

const activeDuration = Math.max(...activeDurations);
const minimumDuration = 60 * 60;

if (endReason === "choice" && activeDuration < minimumDuration) {
  const minutesRemaining = Math.ceil((minimumDuration - activeDuration) / 60);
  ui.notifications.warn(`Totem można wyłączyć za ${minutesRemaining} min.`);
  return;
}

const fatigueCopies = Array.from(this.actor.effects ?? []).filter(
  effect => effect.getFlag("neuroshima", "sourceEffect") === fatigueSource.uuid
);

let remainingFatigue = 0;

for (const fatigueEffect of fatigueCopies) {
  const durationSeconds = Number(fatigueEffect.duration?.seconds ?? 0);
  const rawStartTime = fatigueEffect.duration?.startTime;

  if (!Number.isFinite(durationSeconds) || durationSeconds <= 0) continue;

  if (
    rawStartTime === null
    || rawStartTime === undefined
    || rawStartTime === ""
  ) {
    remainingFatigue += durationSeconds;
    continue;
  }

  const startTime = Number(rawStartTime);

  remainingFatigue += Number.isFinite(startTime)
    ? Math.max(0, durationSeconds - (currentTime - startTime))
    : durationSeconds;
}

await this.actor.deleteEmbeddedDocuments(
  "ActiveEffect",
  activeCopies.map(effect => effect.id)
);

if (fatigueCopies.length) {
  await this.actor.deleteEmbeddedDocuments(
    "ActiveEffect",
    fatigueCopies.map(effect => effect.id)
  );
}

const fatigueDuration = Math.max(
  0,
  Math.ceil(activeDuration + remainingFatigue)
);

if (fatigueDuration > 0) {
  await fatigueSource.applyEffect(this.actor, {
    "duration.seconds": fatigueDuration
  });
}

ui.notifications.info("Postać Totemu została zakończona.");

if (this.effect?.parent?.documentName !== "Actor") return;

const durationSeconds = Number(this.effect.duration?.seconds ?? 0);
const rawStartTime = this.effect.duration?.startTime;

if (
  rawStartTime === null
  || rawStartTime === undefined
  || rawStartTime === ""
) {
  return;
}

const startTime = Number(rawStartTime);

if (
  !Number.isFinite(durationSeconds)
  || durationSeconds <= 0
  || !Number.isFinite(startTime)
) {
  return;
}

const currentTime = Number(game.time?.worldTime ?? startTime);

if (currentTime - startTime < durationSeconds) return;

await this.effect.delete();

const attributeKey =
  args.attributeKey
  ?? args.attribute?.key
  ?? args.weapon?.system?.attribute
  ?? null;

if (
  !attributeKey
  || attributeKey === "cleverness"
) {
  return;
}

const QUARTER_HOUR =
  15 * 60;

const TOTAL_DURATION =
  Number(
    this.effect.duration?.seconds
    ?? 2700
  );

const rawStartTime =
  this.effect.duration?.startTime;

const hasStartTime =
  rawStartTime !== null
  && rawStartTime !== undefined
  && rawStartTime !== ""
  && Number.isFinite(
    Number(rawStartTime)
  );

if (!hasStartTime) {
  return;
}

const startTime =
  Number(rawStartTime);

const currentTime =
  Number(
    game.time?.worldTime
    ?? startTime
  );

const elapsed =
  Math.max(
    0,
    currentTime - startTime
  );

const quartersElapsed =
  Math.floor(
    elapsed / QUARTER_HOUR
  );

const penalty =
  Math.max(
    0,
    30 - quartersElapsed * 10
  );

if (
  elapsed >= TOTAL_DURATION
  || penalty <= 0
) {
  return;
}

args.fields.effectPenalty +=
  penalty;

args.fields.annotations ??= [];

args.fields.annotations.push(
  `Skupienie — powrót na Ziemię: +${penalty}% kary.`
);

if (this.isRecalculation) {
  return;
}

const remaining =
  Number(
    this.effect.duration?.remaining
  );

if (
  Number.isFinite(remaining) &&
  remaining <= 0
) {
  return;
}

const selectedAttribute =
  this.effect.getFlag(
    "neuroshima",
    "machineAttribute"
  );

const testedAttribute =
  args.test?.attributeKey
  ?? args.test?.attribute?.key
  ?? null;

if (
  testedAttribute !==
  selectedAttribute
) {
  return;
}

const currentTests =
  Math.max(
    0,
    Number(
      this.effect.getFlag(
        "neuroshima",
        "machineTestsUsed"
      ) ?? 0
    )
  );

const nextTests =
  currentTests + 1;

if (nextTests < 10) {
  await this.effect.setFlag(
    "neuroshima",
    "machineTestsUsed",
    nextTests
  );

  return;
}

/*
 * Dziesiąty test otrzymał już bonus.
 * Po zakończeniu rzutu usuwamy efekt.
 * Jego deleteEffect zastosuje zmęczenie.
 */
await this.effect.setFlag(
  "neuroshima",
  "machineTestsUsed",
  10
);

await this.deleteEffect();

/*
 * Skrypt ma działać tylko na kopii efektu
 * zastosowanej do aktora, a nie na szablonie
 * przechowywanym na Itemie.
 */
if (
  this.effect?.parent?.documentName !==
  "Actor"
) {
  return;
}

const sourceItem =
  this.effect.sourceItem;

const fatigueTemplate =
  sourceItem?.effects?.contents?.[2];

if (!fatigueTemplate) {
  this.notification(
    "Nie znaleziono efektu zmęczenia pod indeksem 2.",
    "error"
  );

  return;
}

if (
  this.isEffectActive(
    fatigueTemplate,
    this.actor
  )
) {
  return;
}

const fullFatigueDuration = 5 * 60 * 60;

const activeRemaining = Number(this.effect.duration?.remaining);

const overrun = Number.isFinite(activeRemaining) ? Math.max(0,-activeRemaining): 0;

const fatigueDuration =
  Math.max(
    0,
    fullFatigueDuration -
      overrun
  );

if (fatigueDuration <= 0) {
  return;
}

await fatigueTemplate.applyEffect(
  this.actor,
  {
    "duration.seconds":
      fatigueDuration
  }
);

const CHANGE_KEY =
  "system.combat.effectPenalty";

const HOUR =
  60 * 60;

const remaining =
  Number(
    this.effect.duration?.remaining
  );

/*
 * Gdy czas dojdzie do zera, system po wykonaniu
 * skryptów worldTimeUpdate sam usunie efekt.
 */
if (
  !Number.isFinite(remaining) ||
  remaining <= 0
) {
  return;
}

const fatiguePenalty =
  Math.clamp(
    Math.ceil(
      remaining / HOUR
    ) * 10,
    10,
    50
  );

const changes =
  foundry.utils.deepClone(
    this.effect.changes ?? []
  );

const change =
  changes.find(
    entry =>
      entry.key === CHANGE_KEY
  );

if (!change) {
  changes.push({
    key:
      CHANGE_KEY,

    mode:
      CONST.ACTIVE_EFFECT_MODES.ADD,

    value:
      String(fatiguePenalty),

    priority:
      20
  });
} else {
  const currentPenalty =
    Number(change.value);

  /*
   * Brak aktualizacji dokumentu, gdy kara
   * nadal ma tę samą wartość.
   */
  if (
    currentPenalty ===
    fatiguePenalty
  ) {
    return;
  }

  change.mode =
    CONST.ACTIVE_EFFECT_MODES.ADD;

  change.value =
    String(fatiguePenalty);

  change.priority ??=
    20;
}

await this.effect.update({
  changes
});

const disease = this.effect?.parent?.documentName === "Item"
  ? this.effect.parent
  : null;
if (!disease || disease.type !== "disease") return;

const bleedingTypes = new Set(["D", "L", "C", "K"]);
const wounds = (args.wounds ?? []).filter(wound =>
  wound?.forceSkip !== true
  && bleedingTypes.has(wound?.damageType)
);
if (!wounds.length) return;

const flagKey = "hemophiliaPendingWounds";
const stored = disease.getFlag("neuroshima", flagKey);
const pending = Array.isArray(stored)
  ? foundry.utils.deepClone(stored)
  : [];
const now = Number(game.time?.worldTime ?? 0);
const location = args.location ?? "torso";

for (const wound of wounds) {
  pending.push({
    id: foundry.utils.randomID(),
    damageType: wound.damageType,
    damageCategory: wound.damageCategory ?? "physical",
    name: wound.name ?? `Rana ${wound.damageType}`,
    location,
    dueAt: now + 300
  });
}

await disease.setFlag("neuroshima", flagKey, pending);

await this.sendMessage(
  `<p><strong>Hemofilia:</strong> ${wounds.length} rana/rany grożą ponownym obrażeniem po 5 minutach. Zaznacz przyjmowanie lekarstwa na chorobie przed upływem tego czasu, aby zatrzymać krwawienie.</p>`
);

const disease = this.effect?.parent?.documentName === "Item"
  ? this.effect.parent
  : null;
if (!disease || disease.type !== "disease") return;

const flagKey = "hemophiliaPendingWounds";
const stored = disease.getFlag("neuroshima", flagKey);
const pending = Array.isArray(stored)
  ? foundry.utils.deepClone(stored)
  : [];
if (!pending.length) return;

const now = Number(args.worldTime ?? game.time?.worldTime ?? 0);
const overdue = pending.filter(entry =>
  Number.isFinite(Number(entry?.dueAt))
  && Number(entry.dueAt) <= now
);
if (!overdue.length) return;

const future = pending.filter(entry =>
  !Number.isFinite(Number(entry?.dueAt))
  || Number(entry.dueAt) > now
);

if (future.length) {
  await disease.setFlag("neuroshima", flagKey, future);
} else {
  await disease.unsetFlag("neuroshima", flagKey);
}

for (const entry of overdue) {
  await game.neuroshima.CombatHelper.applyDamage(this.actor, {
    wounds: [{
      name: entry.name ?? `Rana ${entry.damageType}`,
      damageType: entry.damageType,
      damageCategory: entry.damageCategory ?? "physical",
      annotation: "Hemofilia — ponowne obrażenie wskutek niezatamowanego krwawienia."
    }],
    location: entry.location ?? "torso",
    source: '<p style="text-align: justify;"><span style="font-family: Special Elite;">Hemofilia — krwawienie nie zostało zatrzymane w ciągu 5 minut.</span></p>',
    withPainResistance: true
  });
}

await this.sendMessage(
  `<p><strong>Hemofilia:</strong> krwawienie nie zostało zatrzymane. Zastosowano ${overdue.length} dodatkową ranę/dodatkowych ran.</p>`
);

const disease = this.effect?.parent?.documentName === "Item"
  ? this.effect.parent
  : null;
if (!disease || disease.type !== "disease") return;
if (args.item?.id !== disease.id) return;

const updateData = args.updateData ?? {};
const medicationValue = Object.prototype.hasOwnProperty.call(
  updateData,
  "system.medication.isTaking"
)
  ? updateData["system.medication.isTaking"]
  : foundry.utils.getProperty(
      updateData,
      "system.medication.isTaking"
    );

if (medicationValue !== true) return;

const flagKey = "hemophiliaPendingWounds";
const stored = disease.getFlag("neuroshima", flagKey);
const pending = Array.isArray(stored)
  ? foundry.utils.deepClone(stored)
  : [];
const now = Number(game.time?.worldTime ?? 0);

const overdue = pending.filter(entry =>
  Number.isFinite(Number(entry?.dueAt))
  && Number(entry.dueAt) <= now
);
const prevented = pending.filter(entry =>
  !Number.isFinite(Number(entry?.dueAt))
  || Number(entry.dueAt) > now
);

if (pending.length) {
  await disease.unsetFlag("neuroshima", flagKey);
}

await disease.update({
  "system.medication.isTaking": false
});

for (const entry of overdue) {
  await game.neuroshima.CombatHelper.applyDamage(this.actor, {
    wounds: [{
      name: entry.name ?? `Rana ${entry.damageType}`,
      damageType: entry.damageType,
      damageCategory: entry.damageCategory ?? "physical",
      annotation: "Hemofilia — ponowne obrażenie wskutek niezatamowanego krwawienia."
    }],
    location: entry.location ?? "torso",
    source: '<p style="text-align: justify;"><span style="font-family: Special Elite;">Hemofilia — krwawienie nie zostało zatrzymane w ciągu 5 minut.</span></p>',
    withPainResistance: true
  });
}

if (prevented.length) {
  await this.sendMessage(
    `<p><strong>Hemofilia:</strong> podano preparat krwiopochodny. Zatrzymano ${prevented.length} oczekujące krwawienie/oczekujących krwawień. Zmniejsz ręcznie liczbę dawek odpowiedniego lekarstwa.</p>`
  );
}

if (overdue.length) {
  await this.sendMessage(
    `<p><strong>Hemofilia:</strong> lek podano za późno dla ${overdue.length} rany/ran. Dodatkowe obrażenia zostały zastosowane.</p>`
  );
}

const medicine = this.item;
if (!medicine || medicine.type !== "gear" || !this.actor) return;

const quantity = Number(medicine.system?.quantity ?? 0);
if (quantity <= 0) {
  this.notification("Brak dawek leku.", "warn");
  return;
}

const sideEffect = medicine.effects.get("s5AP0ErY7Vppbzn9");
if (!sideEffect) {
  this.notification("Nie znaleziono efektu skutku ubocznego.", "error");
  return;
}

const existing = (this.actor.effects ?? []).find(e =>
  e.getFlag?.("neuroshima", "sourceEffect") === sideEffect.uuid
  || e.name === sideEffect.name
);

if (existing) {
  await existing.update({
    disabled: false,
    "duration.seconds": 3600,
    "duration.startTime": game.time.worldTime
  });
} else {
  await sideEffect.applyEffect(this.actor, {
    "duration.seconds": 3600,
    "duration.startTime": game.time.worldTime
  });
}

await medicine.reduceQuantity(1);
this.notification("Zastosowano lek i zużyto 1 dawkę.", "info");

const medicine = this.item;
if (!medicine || medicine.type !== "gear" || !this.actor) return;

const quantity = Number(medicine.system?.quantity ?? 0);
if (quantity <= 0) {
  this.notification("Brak dawek leku.", "warn");
  return;
}

const sideEffect = medicine.effects.get("JbBTMrDD0Ge31BzT");
if (!sideEffect) {
  this.notification("Nie znaleziono efektu skutku ubocznego.", "error");
  return;
}

const existing = (this.actor.effects ?? []).find(e =>
  e.getFlag?.("neuroshima", "sourceEffect") === sideEffect.uuid
  || e.name === sideEffect.name
);

if (existing) {
  await existing.update({
    disabled: false,
    "duration.seconds": 7200,
    "duration.startTime": game.time.worldTime
  });
} else {
  await sideEffect.applyEffect(this.actor, {
    "duration.seconds": 7200,
    "duration.startTime": game.time.worldTime
  });
}

await medicine.reduceQuantity(1);
this.notification("Zastosowano lek i zużyto 1 dawkę.", "info");
